export function ServiceLogo(handle: Handle<SvgProps & { name: string }>) {
  return () => {
    const { name, ...props } = handle.props
    const Component =
      services[name.toLowerCase().replace(/[^a-z0-9]/g, '') as keyof typeof services]
    return Component ? <Component {...props} /> : <span>{name}</span>
  }
}
